// GENERATED by tools/merge_block.py from the six per-section components.
// Do not hand-edit; regenerate.
//
// ONE block for the whole page. Six blocks each cost a `block` table and a
// `_locales` table, doubled for versions — 24 tables that exist only because
// there are six of them. Groups are column prefixes, so folding each section
// into a group pays that once: 42 tables became 22, measured.
//
// The price is that the running order is FROZEN here. An editor cannot drag a
// section or remove one. That was the explicit trade — this page is a designed
// narrative, not an editorial sequence.
//
// Each section keeps its own `rd-yb rd-yb<name>` root class and its own
// anchorId, so rd-yb.css still reaches it and the page's internal links
// (#top, #start) still resolve. It also means the Stage 7 harness can still
// verify one section at a time with --ours ".rd-ybtwo".

// A slice of the block's props, as one section sees them.
type Sec<K extends keyof Props> = NonNullable<Props[K]>

const mediaUrl = (m: unknown): string | undefined =>
  m && typeof m === 'object' && 'url' in m ? ((m as { url?: string }).url ?? undefined) : undefined

const mediaAlt = (m: unknown): string =>
  m && typeof m === 'object' && 'alt' in m ? ((m as { alt?: string }).alt ?? '') : ''
